class _PigeonCodec extends StandardMessageCodec {
  const _PigeonCodec();
  @override
  void writeValue(WriteBuffer buffer, Object? value) {
    if (value is int) {
      buffer.putUint8(4);
      buffer.putInt64(value);
    } else if (value is ComputeUnitsMessage) {
      buffer.putUint8(129);
      writeValue(buffer, value.index);
    } else if (value is MultiArrayDataTypeMessage) {
      buffer.putUint8(130);
      writeValue(buffer, value.index);
    } else if (value is FeatureTypeMessage) {
      buffer.putUint8(131);
      writeValue(buffer, value.index);
    } else if (value is ReshapeFrequencyMessage) {
      buffer.putUint8(132);
      writeValue(buffer, value.index);
    } else if (value is SpecializationStrategyMessage) {
      buffer.putUint8(133);
      writeValue(buffer, value.index);
    } else if (value is ShapeConstraintTypeMessage) {
      buffer.putUint8(134);
      writeValue(buffer, value.index);
    } else if (value is ImageSizeConstraintTypeMessage) {
      buffer.putUint8(135);
      writeValue(buffer, value.index);
    } else if (value is ComputeDeviceKindMessage) {
      buffer.putUint8(136);
      writeValue(buffer, value.index);
    } else if (value is ImageEncodingMessage) {
      buffer.putUint8(137);
      writeValue(buffer, value.index);
    } else if (value is ModelConfigurationMessage) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    } else if (value is ShapeMessage) {
      buffer.putUint8(139);
      writeValue(buffer, value.encode());
    } else if (value is ImageSizeMessage) {
      buffer.putUint8(140);
      writeValue(buffer, value.encode());
    } else if (value is MultiArrayConstraintMessage) {
      buffer.putUint8(141);
      writeValue(buffer, value.encode());
    } else if (value is ImageConstraintMessage) {
      buffer.putUint8(142);
